class HexylError(Exception):
    def __init__(self, msg: str, code: int = 1):
        super().__init__(msg); self.msg = msg; self.code = code

def eprint(s: str):
    sys.stderr.write(s)

def clap_exit(msg: str, usage: bool = True, tip_unknown: Optional[str] = None, usage_line: str = "Usage: executable [OPTIONS] [FILE]"):
    out = f"error: {msg}\n"
    if tip_unknown:
        out += f"\n  tip: to pass '{tip_unknown}' as a value, use '-- {tip_unknown}'\n"
    if usage:
        out += f"\n{usage_line}\n"
    out += "\nFor more information, try '--help'.\n"
    eprint(out)
    raise SystemExit(2)

def duplicate(name: str, display: Optional[str] = None):
    if display is None:
        display = name
    clap_exit(f"the argument '{display}' cannot be used multiple times")

def invalid_enum(opt_display: str, val: str, values: List[str]):
    eprint(f"error: invalid value '{val}' for '{opt_display}'\n  [possible values: {', '.join(values)}]\n\nFor more information, try '--help'.\n")
    raise SystemExit(2)

def invalid_terminal_width(val: str, reason: str):
    eprint(f"error: invalid value '{val}' for '--terminal-width <N>': {reason}\n\nFor more information, try '--help'.\n")
    raise SystemExit(2)

def require_value(args, i, optname):
    if i + 1 >= len(args):
        eprint(f"error: a value is required for '{optname}' but none was supplied\n\nFor more information, try '--help'.\n")
        raise SystemExit(2)
    nxt = args[i+1]
    if nxt.startswith('-') and nxt != '-':
        clap_exit(f"unexpected argument '{nxt[:2] if len(nxt)>2 and nxt[1].isdigit() else nxt}' found", tip_unknown=(nxt[:2] if len(nxt)>2 and nxt[1].isdigit() else nxt))
    return nxt

def set_once(opts: Opts, key: str, val, display: str):
    # length aliases are a single clap argument; duplicates are rejected.
    dup_key = key
    if dup_key in opts.seen:
        disp = {
            'length': '--length <N>', 'skip': '--skip <N>', 'block_size': '--block-size <SIZE>',
            'color': '--color <WHEN>', 'border': '--border <STYLE>', 'character_table': '--character-table <FORMAT>',
            'color_scheme': '--color-scheme <FORMAT>', 'display_offset': '--display-offset <N>',
            'panels': '--panels <N>', 'group_size': '--group-size <N>', 'endianness': '--endianness <FORMAT>',
            'base': '--base <B>', 'terminal_width': '--terminal-width <N>', 'completion': '--completion <SHELL>'
        }.get(key, display)
        duplicate(key, disp)
    opts.seen.add(dup_key)
    setattr(opts, key, val)
    if key == 'color': opts.explicit_color = True
    if key == 'border': opts.explicit_border = True

def parse_args(argv: List[str]) -> Opts:
    opts = Opts()
    positionals = []
    i = 0
    stop = False
    while i < len(argv):
        arg = argv[i]
        if stop:
            positionals.append(arg); i += 1; continue
        if arg == '--':
            stop = True; i += 1; continue
        if arg in ('--help',):
            sys.stdout.write(HELP_LONG); raise SystemExit(0)
        if arg == '-h':
            sys.stdout.write(HELP_SHORT); raise SystemExit(0)
        if arg in ('--version', '-V'):
            sys.stdout.write('hexyl 0.16.0\n'); raise SystemExit(0)
        if arg.startswith('--') and len(arg) > 2:
            body = arg[2:]
            if '=' in body:
                name, val = body.split('=', 1)
                has_eq = True
            else:
                name, val = body, None
                has_eq = False
            if name == 'no-squeezing':
                if 'no_squeezing' in opts.seen: duplicate('no_squeezing', '--no-squeezing')
                opts.seen.add('no_squeezing'); opts.no_squeezing = True; i += 1; continue
            if name == 'plain':
                if 'plain' in opts.seen: duplicate('plain', '--plain')
                opts.seen.add('plain'); opts.plain = True; i += 1; continue
            if name == 'no-characters':
                if opts.seen_no_char: duplicate('no_characters', '--no-characters')
                opts.seen_no_char = True; opts.show_chars = False; i += 1; continue
            if name == 'characters':
                if opts.seen_char: duplicate('characters', '--characters')
                opts.seen_char = True; opts.show_chars = True; i += 1; continue
            if name == 'no-position':
                if opts.seen_no_pos: duplicate('no_position', '--no-position')
                opts.seen_no_pos = True; opts.show_pos = False; i += 1; continue
            if name == 'print-color-table':
                if 'print_color_table' in opts.seen: duplicate('print_color_table', '--print-color-table')
                opts.seen.add('print_color_table'); opts.print_color_table = True; i += 1; continue
            if name == 'include':
                if 'include' in opts.seen: duplicate('include', '--include')
                opts.seen.add('include'); opts.include = True; i += 1; continue
            if name in LONG_VALUE_OPTS:
                key = LONG_VALUE_OPTS[name]
                if not has_eq:
                    val = require_value(argv, i, '--' + name + ' <N>' if name not in ('color','border','base','completion') else '--' + name)
                    i += 1
                set_once(opts, key, val, '--' + name)
                i += 1; continue
            clap_exit(f"unexpected argument '--{name}' found", tip_unknown='--'+name)
        elif arg.startswith('-') and arg != '-':
            # short flags/clusters
            chars = arg[1:]
            j = 0
            while j < len(chars):
                ch = chars[j]
                if ch == '=':
                    clap_exit(f"unexpected argument '-{chars}' found")
                if ch in SHORT_VALUE_OPTS:
                    key = SHORT_VALUE_OPTS[ch]
                    if j + 1 < len(chars):
                        val = chars[j+1:]
                        if val.startswith('='): val = val[1:]
                        set_once(opts, key, val, '-' + ch)
                        j = len(chars)
                    else:
                        val = require_value(argv, i, '-' + ch)
                        set_once(opts, key, val, '-' + ch)
                        i += 1; j = len(chars)
                elif ch == 'v':
                    if 'no_squeezing' in opts.seen: duplicate('no_squeezing', '--no-squeezing')
                    opts.seen.add('no_squeezing'); opts.no_squeezing = True; j += 1
                elif ch == 'p':
                    if 'plain' in opts.seen: duplicate('plain', '--plain')
                    opts.seen.add('plain'); opts.plain = True; j += 1
                elif ch == 'C':
                    if opts.seen_char: duplicate('characters', '--characters')
                    opts.seen_char = True; opts.show_chars = True; j += 1
                elif ch == 'P':
                    if opts.seen_no_pos: duplicate('no_position', '--no-position')
                    opts.seen_no_pos = True; opts.show_pos = False; j += 1
                elif ch == 'e':
                    if 'endianness' in opts.seen: duplicate('endianness', '--endianness <FORMAT>')
                    opts.seen.add('endianness'); opts.endianness = 'little'; j += 1
                elif ch == 'i':
                    if 'include' in opts.seen: duplicate('include', '--include')
                    opts.seen.add('include'); opts.include = True; j += 1
                elif ch == 'h':
                    sys.stdout.write(HELP_SHORT); raise SystemExit(0)
                elif ch == 'V':
                    sys.stdout.write('hexyl 0.16.0\n'); raise SystemExit(0)
                else:
                    clap_exit(f"unexpected argument '-{ch}' found", tip_unknown='-'+ch)
            i += 1; continue
        else:
            positionals.append(arg); i += 1; continue
    if len(positionals) > 1:
        clap_exit(f"unexpected argument '{positionals[1]}' found")
    opts.file = positionals[0] if positionals else None
    # Plain is an aggregate flag. Explicit color/border options override its color/border, but characters/position remain hidden.
    if opts.plain:
        opts.show_chars = False
        opts.show_pos = False
        if not opts.explicit_border: opts.border = 'none'
        if not opts.explicit_color: opts.color = 'never'
    if opts.color is None: opts.color = 'always'
    if opts.border is None: opts.border = 'unicode'
    validate_enums(opts)
    return opts

def validate_enums(opts: Opts):
    if opts.color not in ('always','auto','never','force'):
        invalid_enum('--color <WHEN>', opts.color, ['always','auto','never','force'])
    if opts.border not in ('unicode','ascii','none'):
        invalid_enum('--border <STYLE>', opts.border, ['unicode','ascii','none'])
    if opts.character_table not in ('default','ascii','codepage-1047','codepage-437','braille'):
        invalid_enum('--character-table <FORMAT>', opts.character_table, ['default','ascii','codepage-1047','codepage-437','braille'])
    if opts.color_scheme not in ('default','gradient'):
        invalid_enum('--color-scheme <FORMAT>', opts.color_scheme, ['default','gradient'])
    if opts.endianness not in ('little','big'):
        invalid_enum('--endianness <FORMAT>', opts.endianness, ['little','big'])
    if normalize_base(opts.base) is None:
        invalid_enum('--base <B>', opts.base, ['binary','octal','decimal','hexadecimal'])
    if opts.completion is not None and opts.completion not in ('bash','elvish','fish','powershell','zsh'):
        invalid_enum('--completion <SHELL>', opts.completion, ['bash','elvish','fish','powershell','zsh'])

def normalize_base(v: str) -> Optional[str]:
    m = {
        'binary':'binary','bin':'binary','b':'binary',
        'octal':'octal','oct':'octal','o':'octal',
        'decimal':'decimal','dec':'decimal','d':'decimal',
        'hexadecimal':'hexadecimal','hex':'hexadecimal','x':'hexadecimal',
    }
    return m.get(v)

UNITS_DEC = {'kb':1000,'kB':1000,'KB':1000,'mb':1000**2,'mB':1000**2,'MB':1000**2,
             'gb':1000**3,'gB':1000**3,'GB':1000**3,'tb':1000**4,'tB':1000**4,'TB':1000**4,
             'pb':1000**5,'pB':1000**5,'PB':1000**5}
UNITS_BIN = {'kib':1024,'kiB':1024,'KiB':1024,'Kib':1024,
             'mib':1024**2,'miB':1024**2,'MiB':1024**2,'Mib':1024**2,
             'gib':1024**3,'giB':1024**3,'GiB':1024**3,'Gib':1024**3,
             'tib':1024**4,'tiB':1024**4,'TiB':1024**4,'Tib':1024**4,
             'pib':1024**5,'piB':1024**5,'PiB':1024**5,'Pib':1024**5}

def parse_count_raw(s: str, block_size: int, allow_negative: bool, context: str) -> Tuple[int,bool]:
    orig = s
    neg = False
    if s.startswith('-'):
        neg = True; s = s[1:]
        if not allow_negative:
            raise HexylError(f"Error: failed to parse `{context}` arg \"{orig}\" as byte count\n\nCaused by:\n    negative offset specified, but only positive offsets (counts) are accepted in this context\n")
    elif s.startswith('+'):
        s = s[1:]
    if s.startswith('0x'):
        part = s[2:]
        try:
            n = int(part, 16)
        except ValueError as e:
            reason = 'cannot parse integer from empty string' if part == '' else 'invalid digit found in string'
            raise HexylError(f"Error: failed to parse `{context}` arg \"{orig}\" as byte count\n\nCaused by:\n    0: failed to parse integer part\n    1: {reason}\n")
        return (-n if neg else n), neg
    m = re.match(r'^(\d+)(.*)$', s)
    if not m:
        raise HexylError(f"Error: failed to parse `{context}` arg \"{orig}\" as byte count\n\nCaused by:\n    \"{orig}\" is not of the expected form <pos-integer>[<unit>]\n")
    n = int(m.group(1)); unit = m.group(2)
    mult = 1
    if unit:
        if unit in UNITS_DEC: mult = UNITS_DEC[unit]
        elif unit in UNITS_BIN: mult = UNITS_BIN[unit]
        elif unit in ('block','blocks'): mult = block_size
        else:
            raise HexylError(f"Error: failed to parse `{context}` arg \"{orig}\" as byte count\n\nCaused by:\n    invalid unit \"{unit}\"\n")
    val = n * mult
    return (-val if neg else val), neg

def parse_block_size(s: str) -> int:
    if s.startswith('-'):
        raise HexylError(f"Error: \"{s}\" is not of the expected form <pos-integer>[<unit>]\n")
    val, _ = parse_count_raw(s, 512, False, '--block-size')
    if val <= 0:
        raise HexylError("Error: block size argument must be positive\n")
    return val

def parse_panels_value(s: str) -> Optional[int]:
    if s == 'auto': return None
    try:
        if not re.match(r'^\d+$', s):
            raise ValueError('invalid digit found in string')
        n = int(s)
        if n == 0:
            raise HexylError('zero')
        return n
    except HexylError:
        raise HexylError(f"Error: failed to parse `--panels` arg \"{s}\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type\n")
    except Exception:
        raise HexylError(f"Error: failed to parse `--panels` arg \"{s}\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string\n")

def parse_terminal_width(s: str) -> int:
    try:
        if not re.match(r'^\d+$', s): raise ValueError('invalid digit found in string')
        n = int(s)
    except Exception as e:
        invalid_terminal_width(s, 'invalid digit found in string')
    if n == 0:
        invalid_terminal_width(s, 'number would be zero for non-zero type')
    return n

def digit_width(base: str) -> int:
    return {'hexadecimal':2,'decimal':3,'octal':3,'binary':8}[base]

def fmt_byte(b: int, base: str) -> str:
    if base == 'hexadecimal': return f'{b:02x}'
    if base == 'decimal': return f'{b:03d}'
    if base == 'octal': return f'{b:03o}'
    return f'{b:08b}'

def panel_width_for(base: str, group: int) -> int:
    groups = (8 + group - 1)//group
    return 1 + digit_width(base)*8 + groups

def layout_width(panels: int, panel_w: int, show_pos: bool, show_chars: bool) -> int:
    widths = []
    if show_pos: widths.append(8)
    widths += [panel_w]*panels
    if show_chars: widths += [8]*panels
    return sum(widths) + len(widths) + 1  # separators/outer borders

def choose_panels(opts: Opts, base: str, group: int, explicit_panel_val: Optional[int]) -> int:
    if opts.terminal_width is not None and opts.panels is not None:
        eprint("error: the argument '--panels <N>' cannot be used with '--terminal-width <N>'\n\nUsage: executable --color <WHEN> --panels <N> <FILE>\n\nFor more information, try '--help'.\n")
        raise SystemExit(2)
    panel_w = panel_width_for(base, group)
    if explicit_panel_val is not None:
        return explicit_panel_val
    if opts.terminal_width is not None:
        tw = parse_terminal_width(opts.terminal_width)
        return max_fit_panels(tw, panel_w, opts.show_pos, opts.show_chars)
    # default/--panels=auto uses an 80-column fallback; default is capped at two panels.
    n = max_fit_panels(80, panel_w, opts.show_pos, opts.show_chars)
    if opts.panels == 'auto':
        return n
    return min(2, n)

def max_fit_panels(tw: int, panel_w: int, show_pos: bool, show_chars: bool) -> int:
    n = 1
    while True:
        nxt = n + 1
        w = layout_width(nxt, panel_w, show_pos, show_chars)
        threshold = w - nxt if show_chars else w
        if threshold <= tw:
            n = nxt
            if n > 10000: break
        else:
            break
    return n

def border_chars(style: str):
    if style == 'ascii':
        return dict(tl='+',tr='+',bl='+',br='+',h='-',tj='+',bj='+',v='|',sep='|',panel='|')
    if style == 'none':
        return dict(v=' ', sep=' ', panel=' ')
    return dict(tl='┌',tr='┐',bl='└',br='┘',h='─',tj='┬',bj='┴',v='│',sep='│',panel='┊')

def top_bottom(opts: Opts, panels: int, panel_w: int, top=True) -> str:
    if opts.border == 'none': return ''
    bc = border_chars(opts.border)
    cols=[]
    if opts.show_pos: cols.append(8)
    cols += [panel_w]*panels
    if opts.show_chars: cols += [8]*panels
    left = bc['tl'] if top else bc['bl']; right = bc['tr'] if top else bc['br']; join = bc['tj'] if top else bc['bj']
    return left + join.join(bc['h']*w for w in cols) + right

def offset_str(n: int) -> str:
    h = f'{n:x}'
    width = max(8, len(h) + (len(h) % 2))
    return h.zfill(width)

def byte_kind(b: int) -> str:
    if b == 0: return 'null'
    if b in (9,10,12,13,32): return 'whitespace'
    if 33 <= b <= 126: return 'printable'
    if b < 128: return 'other'
    return 'nonascii'

def default_char(b: int) -> str:
    if b == 0: return '⋄'
    if 33 <= b <= 126: return chr(b)
    if b == 32: return ' '
    if b in (9,10,12,13): return '_'
    if b < 128: return '•'
    return '×'

def display_char(b: int, table: str) -> str:
    if table == 'default': return default_char(b)
    if table == 'ascii':
        return chr(b) if 32 <= b <= 126 else '.'
    if table == 'codepage-437':
        return CP437[b]
    if table == 'codepage-1047':
        return EBCDIC1047_DISPLAY[b]
    if table == 'braille':
        if b == 0: return '⋄'
        if b == 9: return '→'
        if b == 10: return '↵'
        if b == 13: return '←'
        if 32 <= b <= 126: return chr(b)
        # bit permutation observed in the braille table
        pat = ((b & 0x01) << 0) | ((b & 0x02) << 2) | ((b & 0x04) >> 1) | ((b & 0x08) << 1) | ((b & 0x10) >> 2) | (b & 0x20) | (b & 0x40) | (b & 0x80)
        return chr(0x2800 + pat)
    return default_char(b)

def parse_color_value(s: str) -> Optional[str]:
    t = s.strip().lower().replace('-', ' ')
    bright = False
    if t.startswith('bright '):
        bright = True; t = t[7:]
    if t in STD_COLOR_CODES:
        code = STD_COLOR_CODES[t] + (60 if bright else 0)
        return f'\x1b[{code}m'
    if re.match(r'^#[0-9a-fA-F]{6}$', s.strip()):
        hx = s.strip()[1:]
        r,g,b = int(hx[0:2],16), int(hx[2:4],16), int(hx[4:6],16)
        return f'\x1b[38;2;{r};{g};{b}m'
    return None

def color_palette(scheme: str):
    # category colors; gradient uses per-byte colors but keeps the offset color configurable.
    pal = {
        'null': '\x1b[90m', 'printable': '\x1b[36m', 'whitespace': '\x1b[32m',
        'other': '\x1b[32m', 'nonascii': '\x1b[33m', 'offset': '\x1b[90m'
    }
    env_map = {
        'HEXYL_COLOR_ASCII_PRINTABLE':'printable', 'HEXYL_COLOR_ASCII_WHITESPACE':'whitespace',
        'HEXYL_COLOR_ASCII_OTHER':'other', 'HEXYL_COLOR_NULL':'null',
        'HEXYL_COLOR_NONASCII':'nonascii', 'HEXYL_COLOR_OFFSET':'offset'
    }
    for env,k in env_map.items():
        val = os.environ.get(env)
        if val:
            c = parse_color_value(val)
            if c:
                pal[k] = c
    return pal

def color_for_byte(b: int, opts: Opts, pal) -> str:
    if opts.color_scheme == 'gradient':
        r,g,bb = GRADIENT[b]
        return f'\x1b[38;2;{r:03d};{g:03d};{bb:03d}m'
    return pal[byte_kind(b)]

def should_color(opts: Opts) -> bool:
    if opts.color == 'never': return False
    if os.environ.get('NO_COLOR') is not None and opts.color != 'force': return False
    if opts.color == 'auto': return sys.stdout.isatty()
    return True

def sgr_wrap(text: str, color: str, enable: bool) -> str:
    return color + text + RESET if enable else text

def format_group_bytes(bs: bytes, base: str, group: int, endian: str) -> List[Tuple[int,str]]:
    out=[]
    for gstart in range(0, len(bs), group):
        group_bytes = list(bs[gstart:gstart+group])
        disp = list(reversed(group_bytes)) if endian == 'little' else group_bytes
        for b in disp:
            out.append((b, fmt_byte(b, base)))
    return out

def color_segments_byte_text(items: List[Tuple[int,str]], opts: Opts, pal, enable: bool, sep_after_group: List[bool], pad: str) -> str:
    if not enable:
        s=''
        for idx,(b,t) in enumerate(items):
            s += t
            if sep_after_group[idx]: s += ' '
        return s + pad
    s=''; cur=None
    for idx,(b,t) in enumerate(items):
        c = color_for_byte(b, opts, pal)
        if c != cur:
            s += c; cur = c
        s += t
        if sep_after_group[idx]: s += ' '
    if pad:
        if items:
            # Padding of partial panels remains in the last byte color.
            if cur is None:
                c = color_for_byte(items[-1][0], opts, pal); s += c; cur = c
            s += pad + RESET
        else:
            s += pad + RESET
    else:
        if cur is not None: s += RESET
    return s

def render_hex_panel(bs: bytes, opts: Opts, base: str, group: int, panel_w: int, panel_index: int, pal, enable_color: bool) -> str:
    endian = opts.endianness
    # visible representation with groups and endian ordering
    groups=[]
    for gstart in range(0, len(bs), group):
        gb = list(bs[gstart:gstart+group])
        if endian == 'little': gb = list(reversed(gb))
        groups.append(gb)
    visible = ' '
    items=[]; sep_flags=[]
    for gi,gb in enumerate(groups):
        for bi,b in enumerate(gb):
            items.append((b, fmt_byte(b, base)))
            # separator after the last byte of a group if more byte groups follow
            sep_flags.append(bi == len(gb)-1 and gi != len(groups)-1)
    body_visible_len = sum(len(t) for _,t in items) + sum(1 for f in sep_flags if f)
    full_panel = (len(bs) == 8)
    trailing_uncolored = 0
    pad_colored = ''
    if full_panel:
        trailing_uncolored = panel_w - 1 - body_visible_len
        if trailing_uncolored < 0: trailing_uncolored = 0
    else:
        pad_len = panel_w - 1 - body_visible_len
        if pad_len < 0: pad_len = 0
        pad_colored = ' ' * pad_len
    # no-position quirk: the leading blank of the first data panel is painted as an offset.
    if enable_color and (not opts.show_pos) and panel_index == 0:
        lead = pal['offset'] + ' '
    else:
        lead = ' '
    body = color_segments_byte_text(items, opts, pal, enable_color, sep_flags, pad_colored)
    if enable_color and (not opts.show_pos) and panel_index == 0 and items:
        # body starts with its own color; no reset needed for the offset-colored leading space.
        pass
    return lead + body + (' ' * trailing_uncolored)

def render_char_panel(bs: bytes, opts: Opts, pal, enable_color: bool) -> str:
    chars = [display_char(b, opts.character_table) for b in bs]
    pad_len = 8 - len(chars)
    if not enable_color:
        return ''.join(chars) + ' '*pad_len
    s=''; cur=None
    for b,ch in zip(bs, chars):
        c = color_for_byte(b, opts, pal)
        if c != cur:
            s += c; cur = c
        s += ch
    if pad_len:
        if bs:
            if cur is None:
                c = color_for_byte(bs[-1], opts, pal); s += c; cur = c
            s += ' '*pad_len + RESET
        else:
            s += ' '*pad_len + RESET
    else:
        if cur is not None: s += RESET
    return s

def blank_hex_panel(panel_w: int, enable_color: bool) -> str:
    return ' '*panel_w + (RESET if enable_color else '')

def blank_char_panel(enable_color: bool) -> str:
    return ' '*8 + (RESET if enable_color else '')

def render_row(row: bytes, pos: int, opts: Opts, base: str, group: int, panels: int, panel_w: int, pal, enable_color: bool) -> str:
    bc = border_chars(opts.border)
    parts=[bc['v']]
    if opts.show_pos:
        off = offset_str(pos)
        parts.append(sgr_wrap(off, pal['offset'], enable_color)); parts.append(bc['sep'])
    for p in range(panels):
        if p: parts.append(bc['panel'])
        bs = row[p*8:(p+1)*8]
        parts.append(render_hex_panel(bs, opts, base, group, panel_w, p, pal, enable_color))
    if opts.show_chars:
        parts.append(bc['sep'])
        for p in range(panels):
            if p: parts.append(bc['panel'])
            bs = row[p*8:(p+1)*8]
            parts.append(render_char_panel(bs, opts, pal, enable_color))
    parts.append(bc['v'])
    return ''.join(parts)

def render_blank_marker(pos: Optional[int], star: bool, opts: Opts, panels: int, panel_w: int, pal, enable_color: bool) -> str:
    bc = border_chars(opts.border)
    parts=[bc['v']]
    if opts.show_pos:
        if star:
            field = (pal['offset'] + '*' + RESET + ' '*7) if enable_color else '*       '
        else:
            field = sgr_wrap(offset_str(pos or 0), pal['offset'], enable_color)
        parts.append(field); parts.append(bc['sep'])
        first_star_in_hex = False
    else:
        first_star_in_hex = star
    for p in range(panels):
        if p: parts.append(bc['panel'])
        if first_star_in_hex and p == 0:
            if enable_color:
                parts.append(pal['offset'] + pal['offset'] + '*' + RESET + ' '*(panel_w-1) + RESET)
            else:
                parts.append('*' + ' '*(panel_w-1))
        else:
            parts.append(blank_hex_panel(panel_w, enable_color))
    if opts.show_chars:
        parts.append(bc['sep'])
        for p in range(panels):
            if p: parts.append(bc['panel'])
            parts.append(blank_char_panel(enable_color))
    parts.append(bc['v'])
    return ''.join(parts)

def render_empty(opts: Opts, selected_panels: int, group: int, enable_color: bool) -> str:
    # Observed quirk: empty rendering ignores base and uses hex-width panels; content row always uses two data panels.
    panel_w = panel_width_for('hexadecimal', group)
    out=[]
    top = top_bottom(opts, selected_panels, panel_w, True)
    bot = top_bottom(opts, selected_panels, panel_w, False)
    if top: out.append(top)
    cols=[]
    if opts.show_pos: cols.append(' '*8)
    msg = ' No content' + ' '*(panel_w - len(' No content'))
    cols.append(msg)
    cols.append(' '*panel_w)
    if opts.show_chars:
        cols.append(' '*8); cols.append(' '*8)
    # Empty/content row uses Unicode vertical separators even for ascii/none borders.
    out.append('│' + '│'.join(cols) + '│')
    if bot: out.append(bot)
    return '\n'.join(out) + '\n'

def render(data: bytes, start_offset: int, display_offset: int, opts: Opts, base: str, group: int, panels: int) -> str:
    enable_color = should_color(opts)
    pal = color_palette(opts.color_scheme)
    panel_w = panel_width_for(base, group)
    if len(data) == 0:
        return render_empty(opts, panels, group, enable_color)
    out=[]
    top = top_bottom(opts, panels, panel_w, True)
    bot = top_bottom(opts, panels, panel_w, False)
    if top: out.append(top)
    line_bytes = panels * 8
    prev = None; squeezed = False
    row_start = 0
    while row_start < len(data):
        row = data[row_start:row_start+line_bytes]
        can_sq = (not opts.no_squeezing and prev is not None and len(row)==line_bytes and len(prev)==line_bytes and row == prev and len(set(row)) == 1)
        if can_sq:
            if not squeezed:
                out.append(render_blank_marker(None, True, opts, panels, panel_w, pal, enable_color))
                squeezed = True
        else:
            squeezed = False
            pos = start_offset + display_offset + row_start
            out.append(render_row(row, pos, opts, base, group, panels, panel_w, pal, enable_color))
        prev = row
        row_start += line_bytes
    if squeezed:
        if opts.show_pos:
            out.append(render_blank_marker(start_offset + display_offset + len(data), False, opts, panels, panel_w, pal, enable_color))
        else:
            out.append(render_blank_marker(None, True, opts, panels, panel_w, pal, enable_color))
    if bot: out.append(bot)
    return '\n'.join(out) + '\n'

def read_input(opts: Opts, block_size: int) -> Tuple[bytes,int,Optional[str]]:
    # Returns data, actual start offset, variable basename (for include declarations).
    if opts.file is None:
        raw = sys.stdin.buffer.read()
        name = None
        file_mode = False
    else:
        path = opts.file
        if os.path.isdir(path):
            raise HexylError(f"Error: '{path}' is a directory.\n")
        try:
            with open(path, 'rb') as f:
                raw = f.read()
        except FileNotFoundError:
            raise HexylError("Error: No such file or directory (os error 2)\n")
        except PermissionError:
            raise HexylError("Error: Permission denied (os error 13)\n")
        except OSError as e:
            raise HexylError(f"Error: {e.strerror} (os error {e.errno})\n")
        name = os.path.basename(path)
        file_mode = True
    skip = 0; neg = False
    if opts.skip is not None:
        skip, neg = parse_count_raw(opts.skip, block_size, True, '--skip')
    if neg:
        if not file_mode:
            raise HexylError("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n")
        start = len(raw) + skip
        if start < 0:
            raise HexylError("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).\n")
    else:
        start = skip
    if start > len(raw):
        sliced = b''
    else:
        sliced = raw[start:]
    if opts.length is not None:
        length, _ = parse_count_raw(opts.length, block_size, False, '--length')
        sliced = sliced[:length]
    return sliced, start, name

def render_include(data: bytes, varname: Optional[str]) -> str:
    def lines_for_bytes(bs: bytes) -> List[str]:
        if not bs:
            return ['']
        lines=[]
        for i in range(0, len(bs), 12):
            chunk = bs[i:i+12]
            parts = [f'0x{b:02x}' for b in chunk]
            line = '  ' + ', '.join(parts)
            if i + 12 < len(bs): line += ','
            lines.append(line)
        return lines
    if varname is None:
        if not data: return '\n'
        return '\n'.join(lines_for_bytes(data)) + '\n'
    v = ''.join(c if c.isalnum() else '_' for c in varname)
    out=[f'unsigned char {v}[] = {{']
    out.extend(lines_for_bytes(data))
    out.append('};')
    out.append(f'unsigned int {v}_len = {len(data)};')
    out.append('')
    return '\n'.join(out) + '\n'

def print_color_table():
    pal = color_palette('default')
    sys.stdout.write('hexyl color reference:\n\n')
    sys.stdout.write(pal['null'] + '⋄ NULL bytes (0x00)\n')
    sys.stdout.write(RESET + pal['printable'] + 'a ASCII printable characters (0x20 - 0x7E)\n')
    sys.stdout.write(RESET + pal['whitespace'] + '_ ASCII whitespace (0x09 - 0x0D, 0x20)\n')
    sys.stdout.write(RESET + pal['other'] + '• ASCII control characters (except NULL and whitespace)\n')
    sys.stdout.write(RESET + pal['nonascii'] + '× Non-ASCII bytes (0x80 - 0xFF)\n')
    sys.stdout.write(RESET)

